function indexById<T extends { id: number }>(items: T[]): Record<number, T> {
  const map: Record<number, T> = {};
  for (const item of items) map[item.id] = item;
  return map;
}

const rows = [{ id: 10, name: 'a' }, { id: 20, name: 'b' }];
const byId = indexById(rows);
