solution.code:
function biggest<T extends { length: number }>(items: T[]): T {
  return items.reduce((a, b) => (a.length > b.length ? a : b));
}

console.log(biggest(['hi', 'hello', 'hey']));
console.log(biggest([[1], [1, 2, 3], [1, 2]]));

function pick<T extends object, K extends keyof T>(obj: T, keys: K[]): Pick<T, K> {
  const result = {} as Pick<T, K>;
  for (const key of keys) {
    result[key] = obj[key];
  }
  return result;
}

const user = { id: 1, name: 'Ada', email: 'a@x.io' };
const small = pick(user, ['id', 'name']);
